    @Test void sixteenConcurrentProducersComputeSharedOnceAndPublishTwoIsolatedPackages()throws Exception{
        ExecutorService pool=Executors.newFixedThreadPool(16);CountDownLatch ready=new CountDownLatch(16),go=new CountDownLatch(1);List<Future<List<com.steven.assets.repository.SrppReportRepository.Package>>> futures=new ArrayList<>();
        for(int i=0;i<16;i++)futures.add(pool.submit(()->{ready.countDown();go.await();return publisher.publish(scope,frozen(7,AT,"09:05","same-source"),supported(),extras(),states(7,"09:05"),AT);}));assertThat(ready.await(10,TimeUnit.SECONDS)).isTrue();go.countDown();Set<UUID> runs=new HashSet<>(),bases=new HashSet<>();try{for(var f:futures)for(var p:f.get(30,TimeUnit.SECONDS)){runs.add(p.id());bases.add(p.sharedId());SrppReportEnvelopeValidator.validate(p.content());}}finally{pool.shutdownNow();pool.awaitTermination(10,TimeUnit.SECONDS);}
        assertThat(runs).hasSize(2);assertThat(bases).hasSize(1);verify(calculator,times(1)).shared(any(),any(),any(),any(),any());verify(calculator,times(2)).core(any(),any(),any(),any());assertThat(count("srpp_report_calculation_base")).isEqualTo(1);assertThat(count("srpp_report_calculation_package")).isEqualTo(2);
    }
    @Test void transportClocksDoNotRecalculateButRealSourceChangeCreatesNewImmutableIds()throws Exception{
        var first=publisher.publish(scope,frozen(7,AT,"09:05","stable-source"),supported(),extras(),states(7,"09:05"),AT);var same=publisher.publish(scope,frozen(7,AT.plusSeconds(60),"09:05","stable-source"),supported(),extras(),states(7,"09:05"),AT.plusSeconds(60));assertThat(same).isEqualTo(first);verify(calculator,times(1)).shared(any(),any(),any(),any(),any());
        var changed=publisher.publish(scope,frozen(7,AT.plusSeconds(120),"09:05","new-canonical-revision"),supported(),extras(),states(7,"09:05"),AT.plusSeconds(120));assertThat(changed.getFirst().sharedId()).isNotEqualTo(first.getFirst().sharedId());assertThat(repository.byId(7,first.getFirst().id()).orElseThrow().content()).isEqualTo(first.getFirst().content());assertThat(repository.latest(scope,"Codex").orElseThrow().id()).isEqualTo(changed.getFirst().id());assertThatThrownBy(()->jdbc.update("UPDATE srpp_report_calculation_package SET consumer='Claude' WHERE id=?",first.getFirst().id())).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->jdbc.update("UPDATE srpp_report_calculation_base SET report_slot='12:00' WHERE id=?",first.getFirst().sharedId())).isInstanceOf(RuntimeException.class);
        java.nio.file.Files.writeString(java.nio.file.Path.of("/tmp/task489-report-positive.json"),first.getFirst().content());
    }
    @Test void failedSecondConsumerRollsBackBaseAndFirstConsumerAtomically(){
        doThrow(new IllegalStateException("injected second consumer failure")).when(calculator).core(any(),any(),any(),eq("Claude"));assertThatThrownBy(()->publisher.publish(scope,frozen(7,AT,"09:05","v1"),supported(),extras(),states(7,"09:05"),AT)).isInstanceOf(IllegalStateException.class);assertThat(count("srpp_report_calculation_base")).isZero();assertThat(count("srpp_report_calculation_package")).isZero();
    }
