        ((ObjectNode)facts.path("bearWindow")).put("status","UNAVAILABLE").put("reason","RESERVED_BEAR_WINDOW_SOURCE_UNAVAILABLE");
        for(String key:List.of("tradability:00865B","tradability:00719B","tradability:00697B","bear-window")){ObjectNode body=input.withObject("sources").putObject(key);body.put("status","UNAVAILABLE");body.put("reason",key.equals("bear-window")?"RESERVED_BEAR_WINDOW_SOURCE_UNAVAILABLE":"TRADABILITY_SOURCE_UNAVAILABLE");((ObjectNode)vector.path(key)).put("sha256",SrppJcs.hash(body)).put("coverage","NONE").put("validation","UNAVAILABLE");}
