        var saved=publisher.publish(scope,frozen,supported(),extras(),states(7,"09:05"),AT).getFirst();var bond=SrppJcs.parseStrict(saved.content()).path("modules").get(5);assertThat(bond.path("data").path("legs").get(0).path("lots").asInt()).isEqualTo(2);assertThat(bond.path("data").path("legs").get(3).path("lots").asInt()).isEqualTo(2);java.nio.file.Files.writeString(java.nio.file.Path.of("/tmp/task489-report-actionable-optional.json"),saved.content());
