        var changed=new com.steven.assets.service.srpp.decision.DecisionInputCapturePort.Frozen(MAPPER.convertValue(input.path("facts"),com.steven.assets.service.srpp.decision.DecisionFacts.Input.class),input,vector,original.assetSnapshotId(),original.assetGeneratedAt());var second=publisher.publish(scope,changed,supported(),extras(),states(7,"09:05"),AT.plusSeconds(60)).getFirst();assertThat(second.sharedId()).isNotEqualTo(first.sharedId());var before=SrppJcs.parseStrict(first.content()).path("inputSnapshot");var after=SrppJcs.parseStrict(second.content()).path("inputSnapshot");assertThat(after.path("valuationCaptureId")).isNotEqualTo(before.path("valuationCaptureId"));var oldInput=SrppJcs.parseStrict(before.path("inputBundleJcs").asText());var newInput=SrppJcs.parseStrict(after.path("inputBundleJcs").asText());assertThat(newInput.path("sources").path("assets").path("snapshot")).isEqualTo(oldInput.path("sources").path("assets").path("snapshot"));assertThat(repository.byId(7,first.id()).orElseThrow().content()).isEqualTo(first.content());
