        var frozen=fixtureWithFreshVector(original,input);var state=new LinkedHashMap<String,ObjectNode>();var unavailable=new UnavailableSrppReportConsumerState();for(String consumer:List.of("Codex","Claude"))state.put(consumer,unavailable.read(7,consumer,facts.date(),facts.slot()));
