        ObjectNode frame=(ObjectNode)MAPPER.readTree(java.nio.file.Files.readString(java.nio.file.Path.of("/tmp/task489-size-real-source-frame.json")));ObjectNode sources=(ObjectNode)frame.path("sources");LocalDate date=LocalDate.parse(frame.path("tradingDate").asText());long owner=frame.path("ownerUserId").asLong();Instant at=Instant.now();int symbols=0,daily=0,points=0;
        var histories=mock(com.steven.assets.repository.StockPriceHistoryRepository.class);var price=mock(com.steven.assets.service.PriceQueryService.class,CALLS_REAL_METHODS);var indicator=new com.steven.assets.service.TechnicalIndicatorService(histories,price,mock(com.steven.assets.repository.TwseIndexDailyHistoryRepository.class),mock(com.steven.assets.repository.UsIndexDailyHistoryRepository.class));
        for(var entry:sources.properties())if(entry.getKey().startsWith("market:")){symbols++;ObjectNode body=(ObjectNode)entry.getValue();String market=body.path("market").asText(),code=body.path("symbol").asText();List<com.steven.assets.model.StockPriceHistory> rows=new ArrayList<>();for(var row:frame.path("__indicatorHistory").path(market+":"+code))rows.add(MAPPER.treeToValue(row,com.steven.assets.model.StockPriceHistory.class));when(histories.findByStockCodeAndMarketAndTradingDateBetweenOrderByTradingDateAsc(eq(code),eq(market),any(),any())).thenAnswer(call->{LocalDate from=call.getArgument(2),through=call.getArgument(3);return rows.stream().filter(r->!r.getTradingDate().isBefore(from)&&!r.getTradingDate().isAfter(through)).toList();});for(var row:body.path("daily"))((ObjectNode)row).put("trusted",price.isTrustedClose(MAPPER.treeToValue(row,com.steven.assets.model.StockPriceHistory.class)));daily+=body.path("daily").size();var calculated=indicator.indicatorSeries(code,market,date.minusDays(730),date.minusDays(1));points+=calculated.size();body.set("indicators",SrppReportModuleCalculator.normalize(MAPPER.valueToTree(calculated)));}
